/**
 * King James Version, bundled with the app.
 *
 * The text lives in public/bible/<slug>.json, one file per book, generated by
 * scripts/build-bible.mjs. Because it ships with the app rather than coming
 * from an API, the reader works with no signal at all.
 */

export type Testament = "OT" | "NT";

export interface Book {
  /** Book name as it appears in the source data. */
  source: string;
  /** Name shown to the reader. */
  name: string;
  slug: string;
  chapters: number;
  testament: Testament;
}

