export const TOTAL_CHAPTERS = BOOKS.reduce((sum, b) => sum + b.chapters, 0); // 1189

const BY_SLUG = new Map(BOOKS.map((b) => [b.slug, b]));

export function getBook(slug: string): Book | undefined {
  return BY_SLUG.get(slug);
}

/**
 * "Psalms 23:1" reads oddly; a single psalm is "Psalm 23". Everything else
 * uses its ordinary name.
 */
export function referenceFor(book: Book, chapter: number, verse?: number): string {
  const name = book.slug === "psalms" ? "Psalm" : book.name;
  return verse ? `${name} ${chapter}:${verse}` : `${name} ${chapter}`;
}

/** Previous/next chapter, rolling over book boundaries. */
export function stepChapter(
  book: Book,
  chapter: number,
  direction: 1 | -1
): { book: Book; chapter: number } | null {
  const next = chapter + direction;
  if (next >= 1 && next <= book.chapters) return { book, chapter: next };

  const index = BOOKS.indexOf(book) + direction;
  const neighbour = BOOKS[index];
  if (!neighbour) return null;
  return { book: neighbour, chapter: direction === 1 ? 1 : neighbour.chapters };
}

// --- text ------------------------------------------------------------------

export interface Segment {
  text: string;
  /** Words the translators supplied, printed in italic in a KJV. */
  italic: boolean;
}

export interface Verse {
  number: number;
  /** True when this verse opens a new paragraph in the printed text. */
  paragraph: boolean;
  segments: Segment[];
}

/**
 * Source verses carry two marks: a leading "#" for a paragraph break, and
 * square brackets around words added by the translators.
 */
export function parseVerse(number: number, raw: string): Verse {
  let text = raw;
  let paragraph = false;

  if (text.startsWith("#")) {
    paragraph = true;
    text = text.slice(1).trimStart();
  }

  const segments: Segment[] = [];
  const pattern = /\[([^\]]*)\]/g;
  let cursor = 0;
  let match: RegExpExecArray | null;

  while ((match = pattern.exec(text)) !== null) {
    if (match.index > cursor) {
      segments.push({ text: text.slice(cursor, match.index), italic: false });
    }
    segments.push({ text: match[1], italic: true });
    cursor = match.index + match[0].length;
  }
  if (cursor < text.length) {
    segments.push({ text: text.slice(cursor), italic: false });
  }

  return { number, paragraph, segments };
}

/** Plain text of a verse, for sharing and for note previews. */
export function verseText(verse: Verse): string {
  return verse.segments.map((s) => s.text).join("");
}

// --- loading ---------------------------------------------------------------

interface BookFile {
  name: string;
  chapters: string[][];
}

const cache = new Map<string, Promise<BookFile>>();

function loadBook(book: Book): Promise<BookFile> {
  const existing = cache.get(book.slug);
  if (existing) return existing;

  const request = fetch(`/bible/${book.slug}.json`).then((response) => {
    if (!response.ok) {
      cache.delete(book.slug);
      throw new Error(`Could not load ${book.name} (${response.status})`);
    }
    return response.json() as Promise<BookFile>;
  });

  cache.set(book.slug, request);
  return request;
}

export async function loadChapter(book: Book, chapter: number): Promise<Verse[]> {
  const file = await loadBook(book);
  const raw = file.chapters[chapter - 1];
  if (!raw) throw new Error(`${book.name} has no chapter ${chapter}`);
  return raw.map((text, i) => parseVerse(i + 1, text));
}
